export const getGetOperationAuditUrl = (
  operationId: string,
  params?: GetOperationAuditParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `${process.env.NEXT_PUBLIC_API_BASE_URL ?? "http://localhost:8000"}/v1/operations/${operationId}/audit?${stringifiedParams}`
    : `${process.env.NEXT_PUBLIC_API_BASE_URL ?? "http://localhost:8000"}/v1/operations/${operationId}/audit`;
};

